        return [[rng.randint(lo, hi) for _ in range(c)] for _ in range(r)]
    tests = [fmt([[5]]), fmt([[1, 2, 3]]), fmt([[1], [2], [3]]), fmt([[1, 2], [3, 4]]), fmt([[10**9, -10**9], [-10**9, 10**9]])]
